import React, { useState, useEffect, useRef, useCallback } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

// Safe DB Wrapper for LINE Browser
const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      if (!window.indexedDB) {
        reject(new Error("IndexedDB not supported"));
        return;
      }
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
};

export default function App() {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [view, setView] = useState<'list' | 'scanner' | 'detail'>('list');
  const [selectedCard, setSelectedCard] = useState<BusinessCardData | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [toast, setToast] = useState<{ msg: string; type: 'success' | 'error' } | null>(null);
  const [isDbReady, setIsDbReady] = useState(false);

  // Initialize Data
  useEffect(() => {
    const loadData = async () => {
      try {
        const db = await getDB();
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const request = store.getAll();
        request.onsuccess = () => {
          setCards(request.result.sort((a, b) => b.scannedAt - a.scannedAt));
          setIsDbReady(true);
        };
      } catch (err) {
        console.warn("IndexedDB unavailable (LINE browser?), using memory mode", err);
        // Fail gracefully - user can still use the app but data won't persist after reload
        setIsDbReady(true); 
      }
    };
    loadData();
  }, []);

  const saveCard = async (card: BusinessCardData) => {
    setCards(prev => [card, ...prev]);
    try {
      const db = await getDB();
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).add(card);
    } catch (e) {
      console.warn("Save failed (memory mode only)");
    }
  };

  const deleteCard = async (id: string) => {
    setCards(prev => prev.filter(c => c.id !== id));
    if (view === 'detail') setView('list');
    try {
      const db = await getDB();
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete(id);
    } catch (e) {}
  };

  const handleScan = async (base64: string) => {
    setIsProcessing(true);
    setView('list'); // Return to list to show loading state there or global overlay

    // Create temp task
    const tempId = Date.now().toString();

    try {
      const result = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: tempId,
        scannedAt: Date.now(),
        imageUrl: base64,
        ...result
      };

      await saveCard(newCard);
      setToast({ msg: "名片識別成功", type: 'success' });
    } catch (err: any) {
      console.error(err);
      setToast({ msg: "識別失敗: " + err.message, type: 'error' });
    } finally {
      setIsProcessing(false);
    }
  };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(cards.map(c => ({
      ...c,
      translations: JSON.stringify(c.translations)
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Cards");
    XLSX.writeFile(wb, `QS_Hub_Export_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const showToast = (msg: string, type: 'success' | 'error') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  if (!isDbReady) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-slate-50">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full max-w-lg mx-auto bg-white shadow-2xl relative overflow-hidden">

      {/* Header */}
      <div className="flex-none bg-indigo-600 text-white p-4 pt-safe-top shadow-lg z-20">
        <div className="flex items-center justify-between mt-2">
          <h1 className="text-xl font-bold tracking-tight">QS Hub Scanner</h1>
          <div className="flex gap-2">
            <button onClick={exportExcel} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 active:scale-95 transition-all">
              <i className="fa-solid fa-file-export"></i>
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 overflow-y-auto bg-slate-50 relative scroll-smooth">

        {view === 'list' && (
          <div className="p-4 pb-24 space-y-4 min-h-full">
            {cards.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-[60vh] text-slate-400">
                <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                  <i className="fa-regular fa-address-card text-3xl"></i>
                </div>
                <p>尚無名片資料</p>
                <p className="text-sm mt-2">點擊下方相機按鈕開始掃描</p>
              </div>
            ) : (
              cards.map(card => (
                <div key={card.id} onClick={() => { setSelectedCard(card); setView('detail'); }} 
                     className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 active:scale-[0.98] transition-all flex gap-4 cursor-pointer">
                   <div className="w-12 h-12 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-600 font-bold text-lg shrink-0">
                     {card.firstName?.[0]}
                   </div>
                   <div className="flex-1 min-w-0">
                     <h3 className="font-bold text-slate-800 truncate">{card.firstName} {card.lastName}</h3>
                     <p className="text-xs text-slate-500 truncate">{card.title}</p>
                     <p className="text-xs text-indigo-500 truncate mt-1">{card.company}</p>
                   </div>
                   <div className="flex flex-col items-end gap-1">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-medium ${
                        card.category === 'academic' ? 'bg-emerald-100 text-emerald-700' :
                        card.category === 'employer' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'
                      }`}>
                        {card.category}
                      </span>
                   </div>
                </div>
              ))
            )}
          </div>
        )}

        {view === 'detail' && selectedCard && (
          <div className="p-4 pb-24 space-y-4">
            <button onClick={() => setView('list')} className="flex items-center text-slate-500 text-sm font-medium mb-2 hover:text-indigo-600">
              <i className="fa-solid fa-arrow-left mr-2"></i> 返回列表
            </button>

            <div className="bg-white p-6 rounded-2xl shadow-lg border border-indigo-50 relative overflow-hidden">
               <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/5 rounded-bl-full -mr-8 -mt-8"></div>
               <div className="relative">
                 <h2 className="text-2xl font-bold text-slate-900">{selectedCard.firstName} {selectedCard.lastName}</h2>
                 <p className="text-indigo-600 font-medium mb-4">{selectedCard.title}</p>

                 <div className="space-y-3 text-sm text-slate-600">
                   <div className="flex items-start gap-3">
                     <i className="fa-solid fa-building mt-1 w-4 text-slate-400"></i>
                     <div>
                       <p className="font-medium text-slate-800">{selectedCard.company}</p>
                       <p className="text-xs text-slate-400">{selectedCard.translations?.company}</p>
                     </div>
                   </div>
                   {selectedCard.email && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-envelope w-4 text-slate-400"></i>
                       <a href={`mailto:${selectedCard.email}`} className="text-indigo-600 underline">{selectedCard.email}</a>
                     </div>
                   )}
                   {selectedCard.phone && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-phone w-4 text-slate-400"></i>
                       <a href={`tel:${selectedCard.phone}`} className="text-slate-700">{selectedCard.phone} (市話)</a>
                     </div>
                   )}
                   {selectedCard.mobile && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-mobile-screen w-4 text-slate-400"></i>
                       <a href={`tel:${selectedCard.mobile}`} className="text-slate-700">{selectedCard.mobile} (手機)</a>
                     </div>
                   )}
                   {selectedCard.line && (
                     <div className="flex items-center gap-3">
                       <i className="fa-brands fa-line w-4 text-green-500"></i>
                       <span className="text-slate-700">{selectedCard.line}</span>
                     </div>
                   )}
                   <div className="pt-3 border-t border-slate-100 mt-3">
                     <p className="text-xs text-slate-400 mb-1">AI 摘要</p>
                     <p className="text-xs leading-relaxed bg-slate-50 p-2 rounded text-slate-600">{selectedCard.reasoning}</p>
                   </div>
                 </div>
               </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
               <button onClick={() => deleteCard(selectedCard.id)} className="w-full py-3 rounded-xl border border-red-200 text-red-500 font-bold bg-white active:bg-red-50">
                 刪除
               </button>
            </div>
          </div>
        )}

        {view === 'scanner' && (
          <div className="absolute inset-0 z-50 bg-black">
             <CameraScanner onCapture={handleScan} onClose={() => setView('list')} />
          </div>
        )}
      </div>

      {/* FAB */}
      {view === 'list' && (
        <button 
          onClick={() => setView('scanner')}
          className="absolute bottom-8 left-1/2 -translate-x-1/2 w-16 h-16 bg-indigo-600 rounded-full text-white shadow-2xl shadow-indigo-500/40 flex items-center justify-center active:scale-90 transition-all z-30"
        >
          <i className="fa-solid fa-camera text-2xl"></i>
        </button>
      )}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="absolute inset-0 bg-white/90 backdrop-blur-sm z-50 flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
          <h3 className="font-bold text-slate-800 text-lg mb-2">AI 正在分析名片</h3>
          <p className="text-slate-500 text-sm animate-pulse">正在提取：姓名、電話、手機、Line ID...</p>
        </div>
      )}

      {/* Toast */}
      {toast && (
        <div className={`absolute top-6 left-1/2 -translate-x-1/2 px-4 py-2 rounded-full text-white text-sm font-bold shadow-lg z-50 animate-fade-in-down ${
          toast.type === 'success' ? 'bg-emerald-500' : 'bg-red-500'
        }`}>
          {toast.type === 'success' ? <i className="fa-solid fa-check mr-2"></i> : <i className="fa-solid fa-circle-exclamation mr-2"></i>}
          {toast.msg}
        </div>
      )}

      <style>{`
        @keyframes fade-in-down {
          0% { opacity: 0; transform: translate(-50%, -20px); }
          100% { opacity: 1; transform: translate(-50%, 0); }
        }
        .animate-fade-in-down { animation: fade-in-down 0.3s ease-out forwards; }
      `}</style>
    </div>
  );
}

import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const stopTracks = () => {
    if (stream) {
      stream.getTracks().forEach(track => {
        try { track.stop(); } catch (e) {}
      });
      setStream(null);
    }
    setIsReady(false);
    if (videoRef.current) videoRef.current.srcObject = null;
  };

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    stopTracks();

    try {
      // 嘗試優先使用後置鏡頭
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
            facingMode: "environment",
            width: { ideal: 1920 }, 
            height: { ideal: 1080 } 
        }, 
        audio: false 
      });

      setStream(mediaStream);

      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().then(() => {
            setIsReady(true);
            setIsLoading(false);
          }).catch(err => {
             console.error("Play error:", err);
             // 部分瀏覽器需使用者互動才能播放，但這裡我們已在 click event chain 中
          });
        };
      }
    } catch (err: any) {
      console.error(err);
      setIsLoading(false);
      // LINE 瀏覽器常見錯誤提示優化
      setError("無法啟動相機。請確認已允許瀏覽器存取相機權限，或嘗試使用系統預設瀏覽器開啟。");
    }
  };

  // 元件掛載時不要自動啟動，等待使用者互動或確保環境穩定
  // 許多 In-App Browser 禁止自動播放影片
  useEffect(() => {
    startCamera(); // 嘗試自動啟動，但如果失敗會顯示 UI 引導
    return () => stopTracks();
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        onCapture(canvas.toDataURL('image/jpeg', 0.9).split(',')[1]);
        stopTracks();
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-slate-800 relative overflow-hidden">
      {/* 隱藏的 Video 元素，樣式確保它佔滿畫面 */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        muted 
        className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 ${isReady ? 'opacity-100' : 'opacity-0'}`} 
      />

      {/* 載入中或未就緒狀態介面 - 避免黑屏 */}
      {!isReady && (
        <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-slate-800 z-20">
          <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mb-6 animate-pulse">
             {isLoading ? <i className="fa-solid fa-spinner fa-spin text-3xl text-indigo-400"></i> : <i className="fa-solid fa-camera text-3xl text-slate-400"></i>}
          </div>
          <h3 className="text-white font-bold text-xl mb-3">{isLoading ? "正在啟動相機..." : "相機準備中"}</h3>
          <p className="text-slate-400 text-sm mb-8 max-w-xs mx-auto leading-relaxed">
            {error || "若畫面全黑請稍候。如果長時間無反應，請點擊下方按鈕重試。"}
          </p>

          {error && (
             <button onClick={startCamera} className="bg-indigo-600 text-white py-3 px-8 rounded-full font-bold shadow-lg active:scale-95 transition-all">
                重試相機
             </button>
          )}

          <button onClick={onClose} className="mt-6 text-slate-500 text-sm underline">
            取消並返回
          </button>
        </div>
      )}

      {/* 掃描框線與操作介面 */}
      {isReady && (
        <>
          <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center z-10">
             {/* 遮罩 */}
             <div className="absolute inset-0 bg-slate-900/60 mask-rect"></div>

             {/* 掃描框 */}
             <div className="relative w-[85%] aspect-[1.586/1] border-2 border-white/30 rounded-xl overflow-hidden shadow-[0_0_0_9999px_rgba(15,23,42,0.6)]">
                <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-500"></div>
                <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-500"></div>
                <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-500"></div>
                <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-500"></div>
                <div className="absolute top-0 w-full h-1 bg-indigo-500/80 shadow-[0_0_15px_rgba(99,102,241,1)] animate-scan-line"></div>
             </div>

             <p className="mt-6 text-white/90 text-sm font-medium tracking-wide bg-black/40 px-4 py-1 rounded-full backdrop-blur-sm border border-white/10">
                將名片置於框內
             </p>
          </div>

          {/* 底部控制列 */}
          <div className="absolute bottom-0 left-0 right-0 p-8 pb-safe-bottom flex items-center justify-center z-30 bg-gradient-to-t from-black/80 to-transparent">
            <button 
                onClick={capture} 
                className="w-20 h-20 rounded-full bg-white border-4 border-indigo-500/30 flex items-center justify-center shadow-lg active:scale-90 transition-transform"
            >
                <div className="w-16 h-16 rounded-full border-2 border-slate-300"></div>
            </button>

            <button 
                onClick={() => { stopTracks(); onClose(); }} 
                className="absolute right-8 bottom-12 w-10 h-10 bg-black/40 text-white rounded-full flex items-center justify-center backdrop-blur-md"
            >
                <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        </>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan-line { 
          0% { top: 0%; opacity: 0.6; }
          50% { opacity: 1; }
          100% { top: 100%; opacity: 0.6; }
        }
        .animate-scan-line { animation: scan-line 2.5s infinite linear; }
      `}</style>
    </div>
  );
};

