      <div className="flex-none bg-indigo-600 text-white p-4 pt-safe-top shadow-lg z-20">
        <div className="flex items-center justify-between mt-2">
          <h1 className="text-xl font-bold tracking-tight">QS Hub Scanner</h1>
          <div className="flex gap-2">
            <button onClick={exportExcel} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 active:scale-95 transition-all">
              <i className="fa-solid fa-file-export"></i>
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 overflow-y-auto relative scroll-smooth">

        {view === 'list' && (
          <div className="p-4 pb-24 space-y-4 min-h-full">
            {cards.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-4 shadow-sm">
                  <i className="fa-regular fa-address-card text-3xl text-indigo-200"></i>
                </div>
                <p>尚無名片資料</p>
                <p className="text-sm mt-2 text-slate-400">請點擊下方相機按鈕</p>
                <div className="mt-8 p-4 bg-indigo-50 rounded-lg text-xs text-indigo-800 max-w-xs">
                   <p className="mb-1 font-bold">💡 提示</p>
                   若在 LINE 內無法開啟相機，請點擊右上角選單，選擇「用預設瀏覽器開啟」。
                </div>
