               <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/5 rounded-bl-full -mr-8 -mt-8"></div>
               <div className="relative">
                 <h2 className="text-2xl font-bold text-slate-900">{selectedCard.firstName} {selectedCard.lastName}</h2>
                 <p className="text-indigo-600 font-medium mb-4">{selectedCard.title}</p>

                 <div className="space-y-3 text-sm text-slate-600">
                   <div className="flex items-start gap-3">
                     <i className="fa-solid fa-building mt-1 w-4 text-slate-400"></i>
                     <div>
                       <p className="font-medium text-slate-800">{selectedCard.company}</p>
                       <p className="text-xs text-slate-400">{selectedCard.translations?.company}</p>
                     </div>
                   </div>
                   {selectedCard.email && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-envelope w-4 text-slate-400"></i>
                       <a href={`mailto:${selectedCard.email}`} className="text-indigo-600 underline">{selectedCard.email}</a>
                     </div>
                   )}
                   {selectedCard.phone && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-phone w-4 text-slate-400"></i>
                       <a href={`tel:${selectedCard.phone}`} className="text-slate-700">{selectedCard.phone} (市話)</a>
                     </div>
                   )}
                   {selectedCard.mobile && (
                     <div className="flex items-center gap-3">
                       <i className="fa-solid fa-mobile-screen w-4 text-slate-400"></i>
                       <a href={`tel:${selectedCard.mobile}`} className="text-slate-700">{selectedCard.mobile} (手機)</a>
                     </div>
                   )}
                   {selectedCard.line && (
                     <div className="flex items-center gap-3">
                       <i className="fa-brands fa-line w-4 text-green-500"></i>
                       <span className="text-slate-700">{selectedCard.line}</span>
                     </div>
                   )}
                   <div className="pt-3 border-t border-slate-100 mt-3">
                     <p className="text-xs text-slate-400 mb-1">AI 摘要</p>
                     <p className="text-xs leading-relaxed bg-slate-50 p-2 rounded text-slate-600">{selectedCard.reasoning}</p>
                   </div>
                 </div>
               </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
               <button onClick={() => deleteCard(selectedCard.id)} className="w-full py-3 rounded-xl border border-red-200 text-red-500 font-bold bg-white active:bg-red-50">
                 刪除
               </button>
            </div>
          </div>
        )}

        {view === 'scanner' && (
          <div className="absolute inset-0 z-50 bg-black">
             <CameraScanner onCapture={processSingleCapture} onClose={() => setView('list')} />
          </div>
        )}
      </div>

      {/* FAB - 僅在支援環境下顯示 */}
      {view === 'list' && (
        <button 
          onClick={() => setView('scanner')}
          className="absolute bottom-8 left-1/2 -translate-x-1/2 w-16 h-16 bg-indigo-600 rounded-full text-white shadow-2xl shadow-indigo-500/40 flex items-center justify-center active:scale-90 transition-all z-30"
        >
          <i className="fa-solid fa-camera text-2xl"></i>
        </button>
      )}

      {/* Loading Overlay */}
      {isProcessing && (
        <div className="absolute inset-0 bg-white/90 backdrop-blur-sm z-50 flex flex-col items-center justify-center p-8 text-center">
          <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
          <h3 className="font-bold text-slate-800 text-lg mb-2">AI 正在分析名片</h3>
          <p className="text-slate-500 text-sm animate-pulse">正在提取資料...</p>
        </div>
      )}

      {/* Toast */}
      {toast && (
        <div className={`absolute top-6 left-1/2 -translate-x-1/2 px-4 py-2 rounded-full text-white text-sm font-bold shadow-lg z-50 animate-fade-in-down ${
          toast.type === 'success' ? 'bg-emerald-500' : 'bg-red-500'
        }`}>
          {toast.type === 'success' ? <i className="fa-solid fa-check mr-2"></i> : <i className="fa-solid fa-circle-exclamation mr-2"></i>}
          {toast.msg}
        </div>
      )}

      <style>{`
        @keyframes fade-in-down {
          0% { opacity: 0; transform: translate(-50%, -20px); }
          100% { opacity: 1; transform: translate(-50%, 0); }
        }
        .animate-fade-in-down { animation: fade-in-down 0.3s ease-out forwards; }
      `}</style>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { BusinessCardData } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

// --- Shared Utilities ---

const useMediaQuery = (query: string) => {
  const [matches, setMatches] = useState(typeof window !== 'undefined' ? window.matchMedia(query).matches : false);
  useEffect(() => {
    const media = window.matchMedia(query);
    const listener = (e: MediaQueryListEvent) => setMatches(e.matches);
    media.addEventListener('change', listener);
    return () => media.removeEventListener('change', listener);
  }, [query]);
  return matches;
};

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      if (typeof window === 'undefined' || !window.indexedDB) {
        reject(new Error("IndexedDB not supported"));
        return;
      }
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      // Remove data URL prefix
      resolve(result.split(',')[1]);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// --- Main App Component ---

export default function App() {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCard, setSelectedCard] = useState<BusinessCardData | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [view, setView] = useState<'list' | 'scanner' | 'detail'>('list'); // Mobile only
  const [toast, setToast] = useState<{ msg: string; type: 'success' | 'error' } | null>(null);
  const [isEnvironmentReady, setIsEnvironmentReady] = useState(false);

  const isDesktop = useMediaQuery('(min-width: 768px)');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize Data
  useEffect(() => {
    const initApp = async () => {
      setIsEnvironmentReady(true);
      try {
        const db = await getDB();
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const request = store.getAll();
        request.onsuccess = () => {
          const result = request.result || [];
          if (result.length > 0) {
            const sorted = result.sort((a, b) => b.scannedAt - a.scannedAt);
            setCards(sorted);
            if (isDesktop && sorted.length > 0) {
              setSelectedCard(sorted[0]);
            }
          }
        };
      } catch (err) {
        console.warn("Storage warning: Using memory-only mode.", err);
      }
    };
    initApp();
  }, [isDesktop]);

  const saveCard = async (card: BusinessCardData) => {
    setCards(prev => [card, ...prev]);
    setSelectedCard(card);
    try {
      const db = await getDB();
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).add(card);
    } catch (e) { }
  };

  const deleteCard = async (id: string) => {
    const newCards = cards.filter(c => c.id !== id);
    setCards(newCards);
    if (selectedCard?.id === id) {
      setSelectedCard(newCards.length > 0 ? newCards[0] : null);
      if (!isDesktop) setView('list');
    }
    try {
      const db = await getDB();
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete(id);
    } catch (e) { }
  };

  // Logic to process a single base64 image (used by Camera)
  const processSingleCapture = async (base64: string) => {
    setIsProcessing(true);
    if (!isDesktop) setView('list');

    const tempId = Date.now().toString();
    try {
      const result = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: tempId,
        scannedAt: Date.now(),
        imageUrl: base64,
        ...result
      };
      await saveCard(newCard);
      if (!isDesktop) {
        setSelectedCard(newCard);
        setView('detail');
      }
      setToast({ msg: "識別成功", type: 'success' });
    } catch (err: any) {
      console.error(err);
      setToast({ msg: "識別失敗: " + err.message, type: 'error' });
    } finally {
      setIsProcessing(false);
    }
  };

  // Logic to batch process files
  const processBatch = async (files: File[]) => {
    if (files.length === 0) return;

    setIsProcessing(true);
    if (!isDesktop) setView('list');

    let successCount = 0;
    let failCount = 0;

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const displayIndex = i + 1;
        setToast({ msg: `正在處理第 ${displayIndex} / ${files.length} 張名片...`, type: 'success' });

        try {
            const base64 = await fileToBase64(file);
            const tempId = Date.now().toString() + Math.random().toString().slice(2,5);

            // Call API
            const result = await extractCardInfo(base64);

            const newCard: BusinessCardData = {
              id: tempId,
              scannedAt: Date.now(),
              imageUrl: base64,
              ...result
            };

            await saveCard(newCard);
            successCount++;
        } catch (err) {
            console.error(`File ${file.name} failed:`, err);
            failCount++;
        }
    }

    setIsProcessing(false);
    setToast({ 
        msg: `處理完成：成功 ${successCount} 張，失敗 ${failCount} 張`, 
        type: successCount > 0 ? 'success' : 'error' 
    });

    // Auto clear toast after 5s
    setTimeout(() => setToast(null), 5000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processBatch(Array.from(e.target.files));
    }
    e.target.value = ''; // Reset input
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
       // Filter images only
       const files = Array.from(e.dataTransfer.files) as File[];
       const imageFiles = files.filter(f => f.type.startsWith('image/'));
       if (imageFiles.length > 0) {
           processBatch(imageFiles);
       } else {
           setToast({ msg: "請拖拉圖片檔案", type: 'error' });
       }
    }
  };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(cards.map(c => ({
      ...c,
      translations: JSON.stringify(c.translations)
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Cards");
    XLSX.writeFile(wb, `QS_Hub_Export_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  if (!isEnvironmentReady) return null;

  // --- Render Layouts ---

  if (isDesktop) {
    // === DESKTOP LAYOUT ===
    return (
      <div className="flex h-screen w-full bg-slate-50 text-slate-900 font-sans overflow-hidden">
        {/* Toast */}
        {toast && (
          <div className={`fixed top-6 right-6 px-6 py-3 rounded-lg text-white font-bold shadow-xl z-50 animate-fade-in-down ${
            toast.type === 'success' ? 'bg-emerald-600' : 'bg-red-600'
          }`}>
            {toast.type === 'success' ? <i className="fa-solid fa-check mr-2"></i> : <i className="fa-solid fa-circle-exclamation mr-2"></i>}
            {toast.msg}
          </div>
        )}

        {/* Sidebar */}
        <div className="w-80 flex-shrink-0 bg-white border-r border-slate-200 flex flex-col z-10">
          <div className="p-5 border-b border-slate-100 bg-indigo-600 text-white">
            <h1 className="text-xl font-bold flex items-center gap-2">
              <i className="fa-solid fa-id-card"></i> QS Hub
