const DesktopNavBtn = ({ icon, label, active, onClick, count }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-widest flex items-center gap-2 transition-all active:scale-95 ${active ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200/50'}`}>
