     {label}
     {count > 0 && <span className="bg-indigo-600 text-white px-1.5 py-0.5 rounded-full text-[9px]">{count}</span>}
  </button>
);

const Field = ({ label, value, icon, fullWidth }: any) => {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    if(!value) return;
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`${fullWidth ? 'md:col-span-2' : ''} group`}>
       <div className="flex items-center justify-between mb-2">
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
             {icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}
          </label>
          {value && (
             <button onClick={copy} className={`text-[9px] font-bold uppercase tracking-wider transition-colors ${copied ? 'text-emerald-500' : 'text-slate-300 group-hover:text-indigo-400'}`}>
                {copied ? <><i className="fa-solid fa-check"></i> Copied</> : 'Copy'}
             </button>
          )}
       </div>
       <div className="bg-slate-50 border border-slate-200 rounded-xl p-3.5 hover:border-indigo-300 hover:bg-white transition-colors relative">
          <div className={`text-sm font-semibold break-all ${value ? 'text-slate-800' : 'text-slate-300 italic'}`}>
             {value || 'N/A'}
          </div>
       </div>
    </div>
  );
};

