        )}
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[90] animate-fadeIn" onClick={() => setIsSidebarOpen(false)} />}
      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
      `}</style>
    </div>
  );
};

const Field = React.memo(({ label, value, translation, icon, className }: any) => {
  const [copied, setCopied] = useState(false);
  const hasValue = Boolean(value && value.trim().length > 0);
  return (
    <div className={`group min-w-0 ${className}`}>
      <div className="flex items-center justify-between mb-1.5 px-0.5">
        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">{icon && <i className={`fa-solid ${icon} text-indigo-300`}></i>} {label}</label>
        {hasValue && (
          <button onClick={() => { navigator.clipboard.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className={`text-[9px] font-bold uppercase tracking-wider transition-all ${copied ? 'text-emerald-500' : 'text-indigo-400'}`}>
            {copied ? 'Copied' : 'Copy'}
          </button>
        )}
      </div>
      <div className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-xl active:scale-[0.99] relative">
        <div className={`text-[13px] font-semibold leading-relaxed break-all ${hasValue ? 'text-slate-700' : 'text-slate-300 italic'}`}>{hasValue ? value : 'N/A'}</div>
        {hasValue && translation && translation !== value && (
          <div className="mt-2 pt-2 border-t border-slate-100 text-xs font-medium text-slate-500">{translation}</div>
        )}
      </div>
    </div>
  );
});

