                       </h1>
                       <div className="text-base font-semibold text-indigo-600">{selectedCardData.title || '無職稱'}</div>
                    </header>

                    <div>
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                            <i className="fa-solid fa-building"></i> 組織資訊 (Organization)
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <Field label="Company" value={selectedCardData.company} translation={selectedCardData.translations?.company} className="md:col-span-2" />
                            <Field label="Department" value={selectedCardData.department} translation={selectedCardData.translations?.department} className="md:col-span-2" />
                            <Field label="Job Title (Original)" value={selectedCardData.title} translation={selectedCardData.translations?.title} />
                            <Field label="Industry" value={selectedCardData.industry} translation={selectedCardData.translations?.industry} />
                        </div>
                    </div>

                    <div>
                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2 pt-4 border-t border-slate-100">
