  const [selectedCardData, setSelectedCardData] = useState<BusinessCardData | null>(null);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('free');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  // LINE 瀏覽器檢測
  const isLine = useMemo(() => /Line/i.test(navigator.userAgent), []);

  useEffect(() => {
    if (!process.env.API_KEY) {
        console.warn("API KEY is missing from environment");
    }

    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
    if (selectedCardId) {
      if (selectedCardData?.id !== selectedCardId) {
        getCardById(selectedCardId).then(data => {
          if (data) setSelectedCardData(data);
        });
      }
    } else {
      setSelectedCardData(null);
    }
  }, [selectedCardId]);

  const togglePlan = async () => {
    if (plan === 'free') {
        setPlan('paid');
        if (window.aistudio) {
            try {
                const hasKey = await window.aistudio.hasSelectedApiKey();
                if (!hasKey) {
                    await window.aistudio.openSelectKey();
                }
            } catch (e) {
                console.error("Failed to open key selector", e);
            }
        }
    } else {
        setPlan('free');
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });

      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', plan, task.plan === 'paid' ? 1 : 0);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      const { imageUrl, ...newCardMeta } = newCard;
      setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));

    } catch (err: any) {
      if (err.message === 'API_KEY_INVALID') {
        if (window.aistudio) {
          window.aistudio.openSelectKey();
        }
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) {
        performTask({...nextTask, plan}); 
      }
    }
  }, [tasks, isProcessing]); 

  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const XLSX = await import('xlsx');
      let exportData: any[];

      if (targetCategory === 'all') {
        exportData = targetCards.map(c => ({
          '來源 (Source)': c.source || 'QS Hub Scanner',
          '類別 (Category)': c.category,
          '稱謂 (Title/Prefix)': c.prefix || '',
          '姓氏 (Last Name)': c.lastName || '',
          '名字 (First Name)': c.firstName || '',
          '職稱 (Job Title)': c.title || '',
          '公司/機構 (Company)': c.company || '',
          '部門 (Department)': c.department || '',
          '產業 (Industry)': c.industry || '',
          '學科 (Subject)': c.subject || '',
          '電子郵件 (Email)': c.email || '',
          '電話 (Phone)': c.phone || '',
          '國家/地區 (Country)': c.country || '',
          '網站 (Website)': c.website || '',
          '地址 (Address)': c.address || '',
          '備註 (Notes)': c.notes || ''
        }));
      } 
      else if (targetCategory === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Job Title': c.title || '',
          'Department': c.department || '',
          'Institution': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Subject': c.subject || '',
          'Phone': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix || '',
          'First Name': c.firstName || '',
          'Last Name': c.lastName || '',
          'Position': c.title || '',
          'Industry': c.industry || '',
          'Company Name': c.company || '',
          'Country or Territory': c.country || '',
          'Email': c.email || '',
          'Phone': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "QS_Data_Export");

      const fileName = `QS_Export_${targetCategory}_${new Date().toISOString().split('T')[0]}.xlsx`;

      // 改為直接下載，不再嘗試呼叫原生分享 (Share API)
      try {
        XLSX.writeFile(wb, fileName);
      } catch (writeErr) {
        if (isLine) {
            alert("LINE 內建瀏覽器可能限制檔案下載。\n請點擊右上角「...」並選擇「在瀏覽器中開啟」後再次嘗試。");
        } else {
            throw writeErr;
        }
      }

    } catch (err: any) { 
        if (err.name !== 'AbortError') alert("匯出失敗：" + err.message); 
    } finally { 
        setIsExporting(false); 
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const newTasks: ProcessingTask[] = [];
    const filesArray = Array.from(files) as File[];

    for (const f of filesArray) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);

      const previewUrl = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = (event) => resolve(event.target?.result as string);
        reader.readAsDataURL(f);
      });

      newTasks.push({
        id,
        fileName: f.name,
        status: 'pending',
        progress: 0,
        batchIndex: 1,
        plan,
        previewUrl
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const visibleCards = useMemo(() => 
    cards.filter(c => c.category === activeCategory), 
  [cards, activeCategory]);

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* Sidebar */}
      <aside 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 lg:p-6 bg-white/80 backdrop-blur-md border-b border-slate-100 shrink-0 z-10 sticky top-0" style={{ paddingTop: 'calc(1.25rem + var(--sat))' }}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3.5">
               <div className="w-10 h-10 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200 shrink-0">
                 <i className="fa-solid fa-bahai text-lg animate-[spin_10s_linear_infinite]"></i>
               </div>
               <div className="min-w-0">
                 <h2 className="text-[15px] font-bold text-slate-900 tracking-tight leading-none mb-1">QS HUB</h2>
                 <p className="text-[10px] font-medium text-slate-400 tracking-wide uppercase">Scanner Pro</p>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-full text-slate-400 active:bg-slate-200"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="mb-6 flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100">
             <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${plan === 'free' ? 'bg-emerald-400' : 'bg-indigo-500'}`}></div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">
                    {plan === 'free' ? 'Standard (Free)' : 'Pro (Custom Key)'}
                </span>
             </div>
             <button 
                onClick={togglePlan}
                className={`relative w-9 h-5 rounded-full transition-colors duration-200 focus:outline-none ${plan === 'paid' ? 'bg-indigo-600' : 'bg-slate-300'}`}
             >
                <span className={`absolute left-0.5 top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-transform duration-200 ${plan === 'paid' ? 'translate-x-4' : 'translate-x-0'}`}></span>
             </button>
          </div>
          {plan === 'paid' && window.aistudio && (
             <button onClick={() => window.aistudio.openSelectKey()} className="w-full mb-4 py-2 text-[10px] font-bold uppercase tracking-wider text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50 flex items-center justify-center gap-2">
                <i className="fa-solid fa-key"></i> 設定 API Key
             </button>
          )}

          <div className="bg-slate-100/80 p-1 rounded-xl flex gap-1 mb-4">
            <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <div className="flex gap-2">
            <button onClick={() => handleShareOrExport('all')} className="flex-1 py-3 lg:py-2.5 px-3 bg-white border border-slate-200 text-slate-600 rounded-lg text-[11px] lg:text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95">
              <i className={`fa-solid ${isMobile ? 'fa-share-nodes' : 'fa-database'}`}></i> 全資料
            </button>
            <button onClick={() => handleShareOrExport(activeCategory)} className="flex-1 py-3 lg:py-2.5 px-3 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[11px] lg:text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95">
              <i className={`fa-solid ${isMobile ? 'fa-share-from-square' : 'fa-file-excel'}`}></i> {isMobile ? '分享' : '匯出'}
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/50 pb-20 lg:pb-3">
           <div className="grid grid-cols-2 gap-2 pb-10 px-1">
             {visibleCards.length === 0 ? (
                <div className="col-span-2 flex flex-col items-center justify-center py-10 text-slate-400">
                  <i className="fa-regular fa-folder-open text-3xl mb-2 opacity-50"></i>
                  <span className="text-xs font-medium">尚無資料</span>
                </div>
             ) : (
                visibleCards.map(c => (
                  <div 
                    key={c.id} 
                    onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} 
                    className={`
                      group relative p-3 rounded-xl cursor-pointer transition-all duration-200 border flex flex-col items-center text-center gap-2 active:scale-[0.98]
                      ${selectedCardId === c.id ? 'bg-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white border-slate-200/60 hover:border-slate-300'}
                    `}
                  >
                    <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${selectedCardId === c.id ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>
                      {c.lastName.charAt(0)}{c.firstName.charAt(0)}
                    </div>
                    <div className="w-full min-w-0">
                      <div className={`font-bold text-[12px] mb-0.5 tracking-tight truncate ${selectedCardId === c.id ? 'text-indigo-900' : 'text-slate-700'}`}>{c.firstName} {c.lastName}</div>
                      <div className="text-[9px] font-medium text-slate-400 truncate uppercase tracking-wide">{c.company}</div>
                    </div>
                  </div>
               ))
             )}
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden">
        <header className={`h-16 px-4 lg:px-6 border-b border-slate-200 flex items-center justify-between bg-white/80 backdrop-blur-xl shrink-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`} style={{ paddingTop: 'var(--sat)' }}>
           <div className="flex items-center gap-3 lg:gap-4 w-full min-w-0">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-600 shadow-sm active:scale-95"><i className="fa-solid fa-bars-staggered"></i></button>}

             <nav className="flex items-center bg-slate-100 p-1 rounded-2xl overflow-x-auto no-scrollbar max-w-full gap-1 flex-1 lg:flex-none">
                {isMobile && <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />}
                <NavBtn icon="fa-upload" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCardId && (
                  <>
                    <div className="w-px h-4 bg-slate-300 mx-1 shrink-0"></div>
                    <NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />
                  </>
                )}
             </nav>
           </div>
        </header>

        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'camera' && (
            <div className="h-full p-4 lg:p-8 flex flex-col animate-fadeIn">
              <CameraScanner onCapture={async (b64) => { 
                  const id = crypto.randomUUID(); 
                  const res = await fetch(`data:image/jpeg;base64,${b64}`);
                  const blob = (await res.blob()) as Blob;
                  filesMap.current.set(id, blob);
                  setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl: `data:image/jpeg;base64,${b64}` }]);
                  setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          )}

          {viewMode === 'file' && (
            <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp overflow-y-auto">
              <div 
                className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/80 backdrop-blur-lg text-center group active:scale-[0.98] active:border-indigo-400 shadow-[0_20px_50px_-12px_rgba(0,0,0,0.05)] cursor-pointer transition-all duration-300 hover:shadow-xl hover:border-indigo-300 relative overflow-hidden" 
                onClick={() => fileInputRef.current?.click()}
              >
                    {/* Background decoration */}
                    <div className="absolute -top-24 -left-24 w-48 h-48 bg-indigo-50 rounded-full blur-3xl opacity-50 group-hover:scale-150 transition-transform duration-700"></div>
                    <div className="absolute -bottom-24 -right-24 w-48 h-48 bg-emerald-50 rounded-full blur-3xl opacity-50 group-hover:scale-150 transition-transform duration-700"></div>

                    <div className="w-20 h-20 lg:w-24 lg:h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl shadow-indigo-100 relative z-10 animate-float">
                        <i className="fa-solid fa-cloud-arrow-up text-3xl lg:text-4xl text-white"></i>
                    </div>

                    <div className="relative z-10">
                        <h3 className="text-2xl lg:text-3xl font-extrabold text-slate-800 mb-3 tracking-tight">上傳名片照片</h3>
                        <p className="text-slate-400 text-sm lg:text-base font-medium mb-10 max-w-sm mx-auto leading-relaxed">
                            支援 JPG, PNG 格式，請確保名片文字清晰<br/>
                            <span className="text-indigo-500 font-bold">• 可批次選取多張同時分析 •</span>
                        </p>

                        <div className="inline-flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm lg:text-base font-bold uppercase tracking-widest shadow-lg shadow-indigo-200 group-hover:bg-indigo-700 group-hover:translate-y-[-2px] transition-all active:scale-95 active:shadow-none">
                            <i className="fa-solid fa-images"></i> 點擊選取檔案
                        </div>

                        {/* Mobile Tip */}
                        <div className="mt-12 flex flex-col sm:flex-row items-center justify-center gap-6 pt-8 border-t border-slate-100">
                           <div className="flex items-center gap-2.5 text-slate-400">
                              <div className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-xs border border-slate-100"><i className="fa-solid fa-bolt"></i></div>
                              <span className="text-[11px] font-bold uppercase tracking-wider">AI 高速處理</span>
                           </div>
                           <div className="flex items-center gap-2.5 text-slate-400">
                              <div className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-xs border border-slate-100"><i className="fa-solid fa-shield-halved"></i></div>
                              <span className="text-[11px] font-bold uppercase tracking-wider">加密安全保護</span>
                           </div>
                        </div>
                    </div>

                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>

              {/* Tips Section */}
              <div className="mt-8 grid grid-cols-1 sm:grid-cols-3 gap-4 w-full max-w-2xl px-2">
                 <div className="p-4 bg-white/40 rounded-2xl border border-slate-200 flex items-start gap-3">
                    <span className="text-indigo-500 mt-1"><i className="fa-solid fa-lightbulb"></i></span>
                    <p className="text-[11px] text-slate-500 leading-normal font-medium"><b>技巧 1：</b> 避免反光，在充足光線下拍攝可提升 AI 辨識精準度。</p>
                 </div>
                 <div className="p-4 bg-white/40 rounded-2xl border border-slate-200 flex items-start gap-3">
                    <span className="text-indigo-500 mt-1"><i className="fa-solid fa-magnifying-glass"></i></span>
                    <p className="text-[11px] text-slate-500 leading-normal font-medium"><b>技巧 2：</b> 名片盡量平放並填滿鏡頭，畫面越清晰越好。</p>
                 </div>
                 <div className="p-4 bg-white/40 rounded-2xl border border-slate-200 flex items-start gap-3">
                    <span className="text-indigo-500 mt-1"><i className="fa-solid fa-language"></i></span>
                    <p className="text-[11px] text-slate-500 leading-normal font-medium"><b>技巧 3：</b> AI 會自動翻譯職稱與公司，無需手動更改。</p>
                 </div>
              </div>
            </div>
          )}

          {viewMode === 'tasks' && (
            <div className="max-w-2xl mx-auto p-4 lg:p-12 animate-fadeIn h-full overflow-y-auto pb-32">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl lg:text-2xl font-bold text-slate-800 tracking-tight">處理佇列</h2>
                <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold">{tasks.length} 項目</span>
              </div>
              <div className="space-y-3">
                {tasks.map(t => (
                  <div key={t.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between shadow-sm active:scale-[0.99]">
                    <div className="flex items-center gap-4 min-w-0">
                      {t.previewUrl ? (
                         <img src={t.previewUrl} className="w-12 h-12 rounded-lg object-cover border border-slate-200 shrink-0" alt="preview" />
                      ) : (
                        <div className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl flex items-center justify-center shrink-0 ${t.status === 'completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                          <i className={`fa-solid ${t.status === 'completed' ? 'fa-check' : t.status === 'processing' ? 'fa-circle-notch fa-spin' : 'fa-clock'}`}></i>
                        </div>
                      )}

                      <div className="min-w-0">
                        <div className="font-bold text-slate-800 text-sm truncate mb-0.5">{t.fileName}</div>
                        <div className="text-[10px] font-bold uppercase tracking-wider text-slate-400">
                           {t.status === 'completed' ? '已完成' : t.status === 'processing' ? 'AI 分析中...' : '等待中'}
                        </div>
                      </div>
                    </div>
                    {t.status === 'completed' && <button onClick={() => { setSelectedCardId(t.id); setViewMode('detail'); }} className="w-8 h-8 flex items-center justify-center text-slate-300"><i className="fa-solid fa-chevron-right"></i></button>}
                  </div>
                ))}
              </div>
            </div>
          )}

          {selectedCardData && viewMode === 'detail' && (
            <div className="h-full flex flex-col lg:flex-row overflow-hidden animate-fadeIn">
               <div className={`relative flex flex-col bg-black overflow-hidden shadow-inner ${isMobile ? 'h-[40vh] shrink-0' : 'w-[45%] h-full border-r border-slate-800'}`}>
                  <div className="absolute top-4 right-4 z-[70] flex gap-2">
