        id,
        fileName: f.name,
        status: 'pending',
        progress: 0,
        batchIndex: 1,
        plan,
        previewUrl
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

