// App.tsx
import React, { useRef, useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { CardData } from './types';
import GeminiService from './services/geminiService';

interface AppProps {
  cardData: CardData | null;
  selectedCardData: CardData | null;
}

const App: React.FC<AppProps> = ({ cardData, selectedCardData }) => {
  const { t } = useTranslation();
  const [rotation, setRotation] = useState(0);
  const [containerDim, setContainerDim] = useState<{ width: number; height: number }>({ width: 0, height: 0 });
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const imgContainerRef = useRef<HTMLDivElement>(null);
  const [isImageLoaded, setIsImageLoaded] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (!imgContainerRef.current) return;

    const observer = new ResizeObserver((entries) => {
      entries.forEach((entry) => {
        setContainerDim({
          width: entry.contentRect.width,
          height: entry.contentRect.height,
        });
      });
    });

    observer.observe(imgContainerRef.current);

    return () => observer.disconnect();
  }, [selectedCardData]);

  const handleRotate = () => {
    setRotation((prevRotation) => (prevRotation + 90) % 360);
  };

  const calculateImageStyle = () => {
    if (!containerDim.width || !containerDim.height) {
      return { width: '100%', height: '100%', objectFit: 'contain' };
    }

    const isRotated = rotation === 90 || rotation === 270;
    const maxWidth = isRotated ? containerDim.height : containerDim.width;
    const maxHeight = isRotated ? containerDim.width : containerDim.height;

    return {
      maxWidth: `${maxWidth}px`,
      maxHeight: `${maxHeight}px`,
      width: 'auto',
      height: 'auto',
      transition: 'all 0.3s ease',
      objectFit: 'contain',
    };
  };

  if (!selectedCardData) {
    return (
      <div className="flex items-center justify-center h-screen">
        <p>{t('noCardSelected')}</p>
      </div>
    );
  }

  const { imageUrl } = selectedCardData;

  return (
    <div className="flex flex-col h-full bg-gray-100">
      <div className="flex items-center justify-between p-4 bg-white shadow-md">
        <h1 className="text-xl font-bold">{selectedCardData.title}</h1>
      </div>

      <div className="flex-1 w-full h-full flex items-center justify-center relative overflow-hidden p-4" ref={imgContainerRef}>
        <img
          src={imageUrl}
          alt={selectedCardData.title}
          style={calculateImageStyle()}
          className={`
            transition-transform duration-300 ease-in-out 
            ${isImageLoaded ? 'opacity-100' : 'opacity-0'}
          `}
          onLoad={() => setIsImageLoaded(true)}
        />
        <button
          onClick={handleRotate}
          className="absolute bottom-4 right-4 bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
        >
          {t('rotate')}
        </button>
      </div>
    </div>
  );
};

export default App;
```


