/**
 * AI 自動偵測定位 - 使用 Nano Banana (gemini-2.5-flash-image) 獲得更精準的視覺裁切
 */
export const detectBusinessCards = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // 使用 gemini-2.5-flash-image (Nano Banana) 進行視覺任務，它對邊緣偵測較準確
    // 注意：此模型不支援 responseSchema，需自行解析文字
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `Detect the exact bounding boxes of all business cards in the image.

            Rules:
            1. Crop TIGHTLY around the card edges. Exclude background surfaces (tables, mats).
            2. Return ONLY a raw JSON array of arrays.
            3. Format: [[ymin, xmin, ymax, xmax], [ymin, xmin, ymax, xmax], ...]
            4. Coordinates must be normalized to 0-1000 scale.
            5. Do not output Markdown. Do not output 'json' tags. Just the array.`,
          },
        ],
      },
      // gemini-2.5-flash-image 不支援 responseSchema，因此不設定 config
    });

    let text = response.text || "";

    // 清理可能出現的 markdown 標記
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();

    // 嘗試解析 JSON
    try {
        const coords = JSON.parse(text);
        if (Array.isArray(coords)) {
            // 驗證格式是否為二維陣列且內容為數字
            const validBoxes = coords.filter(box => 
                Array.isArray(box) && 
                box.length === 4 && 
                box.every(n => typeof n === 'number')
            ).map(box => ({
                ymin: box[0],
                xmin: box[1],
                ymax: box[2],
                xmax: box[3]
            }));

            if (validBoxes.length > 0) return validBoxes;
        }
    } catch (parseError) {
        console.warn("JSON Parse failed, trying regex fallback", text);
    }

    // 如果 JSON 解析失敗，使用 Regex 暴力提取 [n, n, n, n] 模式
    const matches = text.matchAll(/\[\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\]/g);
    const boxes = [];
    for (const match of matches) {
        boxes.push({
            ymin: parseInt(match[1]),
            xmin: parseInt(match[2]),
            ymax: parseInt(match[3]),
            xmax: parseInt(match[4])
        });
    }

    return boxes;

  } catch (e) {
    console.warn("AI Detection failed:", e);
    return [];
  }
};

