interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

/**
 * 過濾掉被包含在其他框框內的小框框 (例如名片內的文字區塊)
 */
const filterContainedBoxes = (boxes: BoundingBox[]): BoundingBox[] => {
  if (boxes.length <= 1) return boxes;

  // 1. 根據面積大小排序 (由大到小)
  const sorted = boxes.slice().sort((a, b) => {
    const areaA = (a.ymax - a.ymin) * (a.xmax - a.xmin);
    const areaB = (b.ymax - b.ymin) * (b.xmax - b.xmin);
    return areaB - areaA;
  });

  const result: BoundingBox[] = [];

  for (const current of sorted) {
    let isContained = false;
    for (const container of result) {
      // 檢查 current 是否大致位於 container 內部 (允許一點誤差)
      // 使用 10 個單位的容錯 (scale 1000)
      const margin = 20; 
      if (
        current.xmin >= container.xmin - margin &&
        current.xmax <= container.xmax + margin &&
        current.ymin >= container.ymin - margin &&
        current.ymax <= container.ymax + margin
      ) {
        // 如果這個框框幾乎等於容器框框(重複偵測)，也視為 contained (只保留第一個/較大的)
        isContained = true;
        break;
      }
    }
    if (!isContained) {
      result.push(current);
    }
  }

  // 2. 過濾掉面積過小的雜訊 (例如小於總畫面 0.5% 的雜點)
  return result.filter(box => {
    const width = box.xmax - box.xmin;
    const height = box.ymax - box.ymin;
    return width > 20 && height > 20; // 最小尺寸閾值
  });
};

