interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

/**
 * 智慧過濾重疊與合併框 (Smart De-duplication)
 * 解決問題：AI 有時會畫一個大框包住兩張卡片，或者在同一張卡片上畫好幾個框。
 */
const filterOverlappingBoxes = (boxes: BoundingBox[]): BoundingBox[] => {
  // 1. 移除極小的雜訊 (例如面積小於 1000 單位，假設全圖 1000x1000)
  // 這通常是誤判的文字行或噪點
  let activeBoxes = boxes.filter(b => (b.ymax - b.ymin) * (b.xmax - b.xmin) > 1000); 

  // 2. 依照面積由大到小排序
  activeBoxes.sort((a, b) => {
    const areaA = (a.ymax - a.ymin) * (a.xmax - a.xmin);
    const areaB = (b.ymax - b.ymin) * (b.xmax - b.xmin);
    return areaB - areaA;
  });

  const toRemove = new Set<number>();

  for (let i = 0; i < activeBoxes.length; i++) {
    if (toRemove.has(i)) continue;
    const boxA = activeBoxes[i];
    const areaA = (boxA.ymax - boxA.ymin) * (boxA.xmax - boxA.xmin);

    for (let j = i + 1; j < activeBoxes.length; j++) {
      if (toRemove.has(j)) continue;
      const boxB = activeBoxes[j];
      const areaB = (boxB.ymax - boxB.ymin) * (boxB.xmax - boxB.xmin);

      // 計算交集 (Intersection)
      const ymin = Math.max(boxA.ymin, boxB.ymin);
      const xmin = Math.max(boxA.xmin, boxB.xmin);
      const ymax = Math.min(boxA.ymax, boxB.ymax);
      const xmax = Math.min(boxA.xmax, boxB.xmax);

      if (xmin < xmax && ymin < ymax) {
        const intersectionArea = (ymax - ymin) * (xmax - xmin);

        // 計算重疊比例：相對於「較小框 (Box B)」的比例
        // 如果 Box B 有 80% 以上的面積都在 Box A 裡面，視為包含/重疊關係
        const overlapRatioB = intersectionArea / areaB;

        if (overlapRatioB > 0.8) { 
          // 發現重疊/包含。現在要決定刪除哪一個。

          const sizeRatio = areaB / areaA;

          // 判斷邏輯：
          // 如果 Box B (小框) 的面積佔了 Box A (大框) 的 30% 以上 -> 表示 Box B 是一個完整的物體，不是雜訊。
          // 此時 Box A 通常是「錯誤合併的大框」或是「桌子背景」。
          // -> 策略：刪除大框 A，保留小框 B (以及其他可能在 A 裡面的框)。
          if (sizeRatio > 0.3) {
             toRemove.add(i);
             // Box A 已經被判定為「多餘容器」，不需要再拿它跟別人比了
             break; 
          } else {
             // 如果 Box B 非常小 (小於 A 的 30%) -> 表示 Box B 可能是卡片裡面的 Logo 或文字區塊。
             // -> 策略：刪除小框 B，保留大框 A (卡片本體)。
             toRemove.add(j);
          }
        }
      }
    }
  }

  return activeBoxes.filter((_, idx) => !toRemove.has(idx));
};

