interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

/**
 * 智慧過濾：基於中位數面積 (Median Area) 的離群值偵測
 * 假設：在一張照片中，大部份的名片尺寸在視覺上應該是相近的。
 */
const filterBoxesBySizeAndOverlap = (boxes: BoundingBox[]): BoundingBox[] => {
  if (boxes.length === 0) return [];

  // 1. 計算所有框的面積
  const boxesWithArea = boxes.map(b => ({
    ...b,
    area: (b.ymax - b.ymin) * (b.xmax - b.xmin),
    width: b.xmax - b.xmin,
    height: b.ymax - b.ymin
  }));

  // 2. 移除極小的雜訊 (例如面積小於總畫面的 0.5%)
  // 座標範圍是 0-1000，總面積 1,000,000。0.5% = 5000。
  // 降低閾值以免漏掉遠處的小名片，設為 2000
  let activeBoxes = boxesWithArea.filter(b => b.area > 2000);

  // 如果偵測到的數量很少，直接回傳，不做過度過濾
  if (activeBoxes.length < 3) return activeBoxes.map(({area, width, height, ...rest}) => rest);

  // 3. 計算面積中位數 (Median Area)
  const areas = activeBoxes.map(b => b.area).sort((a, b) => a - b);
  const mid = Math.floor(areas.length / 2);
  const medianArea = areas.length % 2 !== 0 ? areas[mid] : (areas[mid - 1] + areas[mid]) / 2;

  // 4. 定義「標準名片大小」的容許範圍
  // 通常名片大小不會差異太大。
  // 上限 1.8倍 (避免把兩張名片框在一起，那樣面積會是 2.0倍+)
  // 下限 0.3倍 (避免框到名片裡的 Logo 或單一文字區塊)
  const lowerBound = medianArea * 0.3;
  const upperBound = medianArea * 1.8;

  activeBoxes = activeBoxes.filter(b => {
    // 過大 -> 可能是合併框
    if (b.area > upperBound) return false;
    // 過小 -> 可能是雜訊
    if (b.area < lowerBound) return false;
    return true;
  });

  // 5. 重疊檢測 (Overlap Check)
  // 如果兩個框重疊嚴重，保留最接近中位數大小的那個
  const toRemove = new Set<number>();

  for (let i = 0; i < activeBoxes.length; i++) {
    if (toRemove.has(i)) continue;
    const boxA = activeBoxes[i];

    for (let j = i + 1; j < activeBoxes.length; j++) {
      if (toRemove.has(j)) continue;
      const boxB = activeBoxes[j];

      // 計算交集
      const ymin = Math.max(boxA.ymin, boxB.ymin);
      const xmin = Math.max(boxA.xmin, boxB.xmin);
      const ymax = Math.min(boxA.ymax, boxB.ymax);
      const xmax = Math.min(boxA.xmax, boxB.xmax);

      if (xmin < xmax && ymin < ymax) {
        const intersectionArea = (ymax - ymin) * (xmax - xmin);
        // 計算重疊佔比
        const overlapA = intersectionArea / boxA.area;
        const overlapB = intersectionArea / boxB.area;

        // 如果重疊超過 20%，視為衝突 (名片通常不會重疊放置)
        if (overlapA > 0.2 || overlapB > 0.2) {
           // 決定留誰：留面積比較接近 Median 的那個
           const diffA = Math.abs(boxA.area - medianArea);
           const diffB = Math.abs(boxB.area - medianArea);

           if (diffA < diffB) {
             toRemove.add(j);
           } else {
             toRemove.add(i);
             break; // boxA 被移除了，不用再跟別人比
           }
        }
      }
    }
  }

  return activeBoxes.filter((_, idx) => !toRemove.has(idx)).map(({area, width, height, ...rest}) => rest);
};

