import { GoogleGenAI, Type } from "@google/genai";
import { ApiPlan, ApiKeyConfig } from "../types";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * 核心：根據配置獲取 AI 實例
 * 嚴格遵守：若是 custom 則使用用戶輸入值；若是 env/aistudio 則使用系統注入值。
 */
const getAiInstance = (keyConfig?: ApiKeyConfig) => {
  // 1. 優先判斷是否為用戶手動輸入的自定義 Key
  if (keyConfig?.source === 'custom' && keyConfig.value && keyConfig.value.trim() !== '') {
    console.debug("[GeminiService] Using Custom API Key");
    return new GoogleGenAI({ apiKey: keyConfig.value.trim() });
  }

  // 2. 否則（系統預設或 AI Studio），使用環境變數中的 API_KEY
  // 依照指令，process.env.API_KEY 是獲取系統或 AI Studio 注入 Key 的唯一途徑
  console.debug("[GeminiService] Using System/AI-Studio API Key from process.env");
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * 提取名片詳細資料
 */
export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  plan: ApiPlan = 'free',
  keyConfig?: ApiKeyConfig,
  retryCount = 0
): Promise<any> => {
  // 每次調用都重新建立實例，確保 API Key 是最新的
  const ai = getAiInstance(keyConfig);

  // 如果是使用自定義 Key 或付費計畫，使用 pro 模型以獲得最佳品質
  const model = (plan === 'paid' || keyConfig?.source === 'custom') ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `你是一位專業的名片資料分析專家，專門為 QS Hub 系統處理全球名片。

【嚴格規則】：
1. 提取名片文字填入對應欄位。若名片為雙語，欄位內容請「優先提取英文」。
2. 針對「職稱、公司、部門、產業、國家、學科」提供高品質中文譯名至 translations 物件。
3. 摘要 (reasoning) 請用繁體中文，解釋你如何分類與提取關鍵資訊。

【稱謂 (prefix) 規則】：
- 僅提取名片上明確標註的稱謂 (如 Mr., Dr., Prof.)。若無標註，請保持空白，嚴禁猜測。

【電子郵件篩選規則】：
- 僅保留一個最主要的信箱。
- 類別為 academic：優先保留 .edu 信箱。
- 其他類別：優先保留非 .edu 的商務信箱。

請以 JSON 格式回傳。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            phone: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                subject: { type: Type.STRING },
                country: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "reasoning", "translations"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    // 如果偵測到 Key 無效，拋出特定錯誤讓 UI 觸發重設
    if (errorMessage.includes("API key not valid") || errorMessage.includes("403") || errorMessage.includes("invalid")) {
        throw new Error("API_KEY_INVALID");
    }
    if ((errorMessage.includes("503") || errorMessage.includes("rate limit")) && retryCount < 2) {
      await sleep(2000 * (retryCount + 1));
      return extractCardInfo(base64Image, mimeType, plan, keyConfig, retryCount + 1);
    }
    throw error;
  }
};

/**
 * AI 自動偵測定位
 */
export const detectBusinessCards = async (
    base64Image: string, 
    mimeType: string = 'image/jpeg',
    keyConfig?: ApiKeyConfig
): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  const ai = getAiInstance(keyConfig);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: "Detect all business cards in this image. Return their bounding boxes as a JSON array of [ymin, xmin, ymax, xmax] in normalized coordinates (0-1000).",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            boxes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER },
                  xmin: { type: Type.NUMBER },
                  ymax: { type: Type.NUMBER },
                  xmax: { type: Type.NUMBER },
                },
                required: ["ymin", "xmin", "ymax", "xmax"]
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    const data = JSON.parse(text);
    return data.boxes || [];
  } catch (e) {
    console.warn("AI Detection failed:", e);
    return [];
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask, ApiPlan, ApiKeyConfig, ApiKeySource } from './types';
import { extractCardInfo, detectBusinessCards } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js worker
const pdfjs = (pdfjsLib as any).default || pdfjsLib;
if (pdfjs.GlobalWorkerOptions) {
    pdfjs.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;
}

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const deleteCardFromDB = async (id: string): Promise<void> => {
  const db = await getDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(id);

    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    request.onerror = () => reject(request.error);
  });
};

const getCardsMetadataFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const items: BusinessCardData[] = [];
      const request = store.openCursor();
      request.onsuccess = (event: any) => {
        const cursor = event.target.result;
        if (cursor) {
          const { imageUrl, ...rest } = cursor.value;
          items.push(rest as BusinessCardData);
          cursor.continue();
        } else {
          resolve(items);
        }
      };
      request.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const getCardById = async (id: string): Promise<BusinessCardData | null> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) { return null; }
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks' | 'cropper';

interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardData, setSelectedCardData] = useState<BusinessCardData | null>(null);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [plan, setPlan] = useState<ApiPlan>('paid');
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);

  // API Key State
  const [apiKeyConfig, setApiKeyConfig] = useState<ApiKeyConfig>({ source: 'env' });
  const [showKeyModal, setShowKeyModal] = useState(false);
  const [tempCustomKey, setTempCustomKey] = useState('');
  const [hasAiStudio, setHasAiStudio] = useState(false);

  // Custom Delete Modal State
  const [deleteConfirmationId, setDeleteConfirmationId] = useState<string | null>(null);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imgContainerRef = useRef<HTMLDivElement>(null);
  const [containerDim, setContainerDim] = useState({ w: 1, h: 1 });

  // Ref to track tasks for cancellation check inside async functions
  const tasksRef = useRef<ProcessingTask[]>([]);

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); 
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);
  const [cropZoom, setCropZoom] = useState(1); 

  const isLine = useMemo(() => /Line/i.test(navigator.userAgent), []);

  // Sync tasks to ref for async access
  useEffect(() => {
    tasksRef.current = tasks;
  }, [tasks]);

  // Poll for window.aistudio
  useEffect(() => {
    const checkAiStudio = () => {
        if ((window as any).aistudio) {
            setHasAiStudio(true);
            return true;
        }
        return false;
    };
    if (!checkAiStudio()) {
        const interval = setInterval(() => {
            if (checkAiStudio()) clearInterval(interval);
        }, 500);
        return () => clearInterval(interval);
    }
  }, []);

  // Load API Key Config from LocalStorage on mount
  useEffect(() => {
    const savedConfig = localStorage.getItem('qs_api_config');
    if (savedConfig) {
        try {
            const parsed = JSON.parse(savedConfig);
            setApiKeyConfig(parsed);
            if (parsed.source === 'custom') setTempCustomKey(parsed.value || '');
        } catch (e) {
            setShowKeyModal(true);
        }
    } else {
        setShowKeyModal(true);
    }
  }, []);

  const handleSaveApiKeyConfig = (source: ApiKeySource, value?: string) => {
      const config: ApiKeyConfig = { source, value: value?.trim() };
      setApiKeyConfig(config);
      localStorage.setItem('qs_api_config', JSON.stringify(config));
      setShowKeyModal(false);

      // 依照開發者指南，若選 AI Studio，我們假設 process.env.API_KEY 已準備好
      if (source === 'aistudio' && (window as any).aistudio) {
          (window as any).aistudio.openSelectKey();
      }
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
    if (selectedCardId) {
      if (selectedCardData?.id !== selectedCardId) {
        getCardById(selectedCardId).then(data => {
          if (data) setSelectedCardData(data);
        });
      }
    } else {
      setSelectedCardData(null);
    }
  }, [selectedCardId]);

  useEffect(() => {
    if (viewMode === 'detail' && imgContainerRef.current) {
        const measure = () => {
             if (imgContainerRef.current) {
                const rect = imgContainerRef.current.getBoundingClientRect();
                if(rect.width > 0 && rect.height > 0) {
                     setContainerDim({ w: rect.width, h: rect.height });
                }
             }
        };
        measure();
        const ro = new ResizeObserver(entries => {
            for (const entry of entries) {
                if (entry.contentRect.width > 0 && entry.contentRect.height > 0) {
                    setContainerDim({ w: entry.contentRect.width, h: entry.contentRect.height });
                }
            }
        });
        ro.observe(imgContainerRef.current);
        const timer = setTimeout(measure, 100);
        return () => {
            ro.disconnect();
            clearTimeout(timer);
        };
    }
  }, [viewMode, selectedCardId]);

  const handleDeleteCard = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteConfirmationId(id);
  };

  const confirmDelete = async () => {
    if (!deleteConfirmationId) return;
    const id = deleteConfirmationId;
    setDeleteConfirmationId(null); 
    const previousCards = [...cards];
    const previousSelectedId = selectedCardId;
    const previousSelectedData = selectedCardData;
    const previousViewMode = viewMode;

    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
        setSelectedCardId(null);
        setSelectedCardData(null);
        setViewMode('file');
    }

    try {
      await deleteCardFromDB(id);
    } catch (err) {
      console.error("Delete failed:", err);
      alert("刪除失敗，系統將還原資料。");
      setCards(previousCards);
      if (previousSelectedId === id) {
          setSelectedCardId(previousSelectedId);
          setSelectedCardData(previousSelectedData);
          setViewMode(previousViewMode);
      }
    }
  };

  const performTask = useCallback(async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });

      // 關鍵：從目前最新的 apiKeyConfig 傳入，確保調用時使用正確的 Key
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', plan, apiKeyConfig);

      const currentTaskState = tasksRef.current.find(t => t.id === task.id);
      if (currentTaskState && currentTaskState.status === 'cancelled') {
          console.log("Task was cancelled, discarding result.");
          return; 
      }

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      const { imageUrl, ...newCardMeta } = newCard;
      setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', resultCardId: newCard.id } : t));

    } catch (err: any) {
      const currentTaskState = tasksRef.current.find(t => t.id === task.id);
      if (currentTaskState && currentTaskState.status === 'cancelled') {
           return;
      }

      if (err.message === 'API_KEY_INVALID') {
          alert("API Key 無效或已過期，請重新設定。");
          setShowKeyModal(true);
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { 
        setIsProcessing(false); 
    }
  }, [apiKeyConfig, plan, isProcessing]);

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask({...nextTask, plan}); 
    }
  }, [tasks, isProcessing, performTask]); 

  const handleCancelTask = (taskId: string) => {
    setTasks(prev => prev.map(t => {
        if (t.id === taskId) return { ...t, status: 'cancelled' };
        return t;
    }));
  };

  const handleStopAllTasks = () => {
      if (!window.confirm("確定要停止所有等待中及進行中的任務嗎？")) return;
      setTasks(prev => prev.map(t => {
          if (t.status === 'pending' || t.status === 'processing') return { ...t, status: 'cancelled' };
          return t;
      }));
  };

  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const XLSX = await import('xlsx');
      let exportData: any[];

      if (targetCategory === 'all') {
        exportData = targetCards.map(c => ({
          '來源 (Source)': c.source || 'QS Hub Scanner', '類別 (Category)': c.category, '稱謂 (Title/Prefix)': c.prefix || '', '姓氏 (Last Name)': c.lastName || '', '名字 (First Name)': c.firstName || '', '職稱 (Job Title)': c.title || '', '公司/機構 (Company)': c.company || '', '部門 (Department)': c.department || '', '產業 (Industry)': c.industry || '', '學科 (Subject)': c.subject || '', '電子郵件 (Email)': c.email || '', '電話 (Phone)': c.phone || '', '國家/地區 (Country)': c.country || '', '網站 (Website)': c.website || '', '地址 (Address)': c.address || '', '備註 (Notes)': c.notes || ''
        }));
      } else if (targetCategory === 'academic') {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner', 'Title': c.prefix || '', 'First Name': c.firstName || '', 'Last Name': c.lastName || '', 'Job Title': c.title || '', 'Department': c.department || '', 'Institution': c.company || '', 'Country or Territory': c.country || '', 'Email': c.email || '', 'Subject': c.subject || '', 'Phone': c.phone || '',
        }));
      } else {
        exportData = targetCards.map(c => ({
          'Source': c.source || 'QS Hub Scanner', 'Title': c.prefix || '', 'First Name': c.firstName || '', 'Last Name': c.lastName || '', 'Position': c.title || '', 'Industry': c.industry || '', 'Company Name': c.company || '', 'Country or Territory': c.country || '', 'Email': c.email || '', 'Phone': c.phone || '',
        }));
      }

      const ws = XLSX.utils.json_to_sheet(exportData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "QS_Data_Export");
      const fileName = `QS_Export_${targetCategory}_${new Date().toISOString().split('T')[0]}.xlsx`;

      try { XLSX.writeFile(wb, fileName); } 
      catch (writeErr) { if (isLine) alert("LINE 內建瀏覽器限制下載，請改用一般瀏覽器。"); else throw writeErr; }

    } catch (err: any) { alert("匯出失敗：" + err.message); } 
    finally { setIsExporting(false); }
  };

  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64.split(',')[1], 'image/jpeg', apiKeyConfig);
      const regions: CropRegion[] = boxes.map(box => ({
        id: crypto.randomUUID(),
        x: (box.xmin / 1000) * 100,
        y: (box.ymin / 1000) * 100,
        w: ((box.xmax - box.xmin) / 1000) * 100,
        h: ((box.ymax - box.ymin) / 1000) * 100
      }));
      setCropRegions(regions);
    } catch (e) { console.warn(e); } 
    finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const scale = 2;
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64);
            setCropRegions([]);
            setCropZoom(1); 
            autoDetectInCropper(b64);
        }
    } catch (e) { alert("無法讀取 PDF 頁面"); } 
    finally { setIsRenderingPdf(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const firstFile = files[0];
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf);
                setCurrentPdfPage(1);
                await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }
    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64);
            setCropRegions([]);
            setCropZoom(1);
            setViewMode('cropper');
            autoDetectInCropper(b64);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }
    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = await new Promise<string>((res) => {
        const reader = new FileReader();
        reader.onload = (ev) => res(ev.target?.result as string);
        reader.readAsDataURL(f);
      });
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
    const pos = getMousePos(e);
    setStartPos(pos);
    if (action === 'draw') {
        setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 });
        setIsDrawing(true);
        setActiveCropId(null);
    } else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    } else if (action === 'resize' && cropId && handle) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) {
        setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) });
    } else if (isMoving && activeCropId && initialRect) {
        setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r));
    } else if (isResizing && activeCropId && initialRect) {
        const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
        setCropRegions(prev => prev.map(r => {
            if (r.id !== activeCropId) return r;
            let { x, y, w, h } = initialRect;
            if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
            if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
            if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
            if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
            return { ...r, x, y, w, h };
        }));
    }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) {
        const newCrop = { ...currentRect, id: crypto.randomUUID() };
        setCropRegions(prev => [...prev, newCrop]);
        setActiveCropId(newCrop.id);
    }
    setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image();
    sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i];
        const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl: URL.createObjectURL(blob) });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); setPdfDoc(null); setCropperImage(null); setViewMode('tasks');
  };

  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);

  const getCleanPrefix = (p?: string) => {
      if (!p) return null;
      const lower = p.trim().toLowerCase();
      return ['null', 'none', 'n/a', 'undefined'].includes(lower) ? null : p;
  };

  const getSourceLabel = (s: ApiKeySource) => {
      switch(s) {
          case 'env': return 'System Default (Host)';
          case 'aistudio': return 'Google AI Studio';
          case 'custom': return 'Custom API Key';
          default: return s;
      }
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      {/* Sidebar */}
      <aside className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 ease-[cubic-bezier(0.2,0.8,0.2,1)] bg-white flex flex-col border-r border-slate-200 lg:w-[320px] shadow-2xl lg:shadow-none ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-5 lg:p-6 bg-white/80 backdrop-blur-md border-b border-slate-100 shrink-0 z-10 sticky top-0" style={{ paddingTop: 'calc(1.25rem + var(--sat))' }}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3.5">
               <div className="w-10 h-10 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200 shrink-0">
                 <i className="fa-solid fa-bahai text-lg animate-[spin_10s_linear_infinite]"></i>
               </div>
               <div className="min-w-0">
                 <h2 className="text-[15px] font-bold text-slate-900 tracking-tight leading-none mb-1">QS HUB</h2>
                 <p className="text-[10px] font-medium text-slate-400 tracking-wide uppercase">Scanner Pro</p>
               </div>
            </div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-full text-slate-400 active:bg-slate-200"><i className="fa-solid fa-xmark text-lg"></i></button>}
          </div>

          <div className="mb-6 bg-slate-50 p-3 rounded-xl border border-slate-200">
             <div className="flex items-center gap-2 mb-3 px-1 justify-between">
                <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full animate-pulse ${apiKeyConfig.source === 'env' ? 'bg-indigo-500' : 'bg-emerald-500'}`}></div>
                    <span className="text-[10px] font-bold uppercase tracking-wider text-slate-700">{getSourceLabel(apiKeyConfig.source)}</span>
                </div>
             </div>
             <button onClick={() => setShowKeyModal(true)} className="w-full py-2.5 bg-white border border-indigo-200 text-indigo-600 rounded-lg text-[10px] font-bold uppercase tracking-wider hover:bg-indigo-50 transition-all flex items-center justify-center gap-2 shadow-sm">
                <i className="fa-solid fa-gear"></i> 設定 API Key (Settings)
             </button>
          </div>

          <div className="bg-slate-100/80 p-1 rounded-xl flex gap-1 mb-4">
            <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>

          <div className="flex gap-2">
            <button onClick={() => handleShareOrExport('all')} className="flex-1 py-3 bg-white border border-slate-200 text-slate-600 rounded-lg text-[11px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95"><i className="fa-solid fa-database"></i> 全資料</button>
            <button onClick={() => handleShareOrExport(activeCategory)} className="flex-1 py-3 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[11px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95"><i className="fa-solid fa-file-excel"></i> 匯出</button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/50 pb-20 lg:pb-3">
           <div className="grid grid-cols-2 gap-2 pb-10 px-1">
             {visibleCards.length === 0 ? (
                <div className="col-span-2 flex flex-col items-center justify-center py-10 text-slate-400">
                  <i className="fa-regular fa-folder-open text-3xl mb-2 opacity-50"></i>
                  <span className="text-xs font-medium">尚無資料</span>
                </div>
             ) : (
                visibleCards.map(c => (
                  <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} className={`group relative p-3 rounded-xl cursor-pointer transition-all duration-200 border flex flex-col items-center text-center gap-2 active:scale-[0.98] ${selectedCardId === c.id ? 'bg-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white border-slate-200/60 hover:border-slate-300'}`}>
                    <button 
                      type="button"
                      onClick={(e) => handleDeleteCard(e, c.id)}
                      className="absolute top-2 right-2 w-9 h-9 bg-white/80 hover:bg-red-500 text-slate-400 hover:text-white rounded-full transition-all flex items-center justify-center shadow-sm z-20"
                      title="刪除"
                    >
                      <i className="fa-solid fa-trash-can text-[12px]"></i>
                    </button>
                    <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${selectedCardId === c.id ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>{c.lastName.charAt(0)}{c.firstName.charAt(0)}</div>
                    <div className="w-full min-w-0">
                      <div className={`font-bold text-[12px] mb-0.5 tracking-tight truncate ${selectedCardId === c.id ? 'text-indigo-900' : 'text-slate-700'}`}>{c.firstName} {c.lastName}</div>
                      <div className="text-[9px] font-medium text-slate-400 truncate uppercase tracking-wide">{c.company}</div>
                    </div>
                  </div>
               ))
             )}
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden">
        <header className={`h-16 px-4 lg:px-6 border-b border-slate-200 flex items-center justify-between bg-white/80 backdrop-blur-xl shrink-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`} style={{ paddingTop: 'var(--sat)' }}>
           <div className="flex items-center gap-3 w-full">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl shadow-sm"><i className="fa-solid fa-bars-staggered"></i></button>}
