const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * 核心：根據配置獲取 AI 實例
 * 嚴格模式：如果是 custom，絕不回退至 process.env.API_KEY
 */
const getAiInstance = (keyConfig?: ApiKeyConfig) => {
  if (keyConfig?.source === 'custom') {
    const val = keyConfig.value?.trim();
    if (!val) throw new Error("CUSTOM_KEY_MISSING");
    console.debug("[GeminiService] Using STRICT Custom Key");
    return new GoogleGenAI({ apiKey: val });
  }

  // 只有在明確選用系統模式時才使用 env
  console.debug("[GeminiService] Using System Default Key");
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  plan: ApiPlan = 'free',
  keyConfig?: ApiKeyConfig,
  retryCount = 0
): Promise<any> => {
  try {
    const ai = getAiInstance(keyConfig);
    // 自定義金鑰強制使用 flash 以免 Pro 權限不足
    const model = (plan === 'paid' && keyConfig?.source !== 'custom') ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Image } },
          { text: "你是一位專業名片分析專家。請提取資訊並以 JSON 回傳。優先提取英文，translations 提供中文。reasoning 請用繁體中文。" },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            phone: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                country: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "reasoning", "translations"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const msg = error?.message || "";
    if (msg.includes("API key not valid") || msg.includes("403") || msg === "CUSTOM_KEY_MISSING") {
      throw new Error("API_KEY_INVALID");
    }
    if ((msg.includes("503") || msg.includes("rate limit")) && retryCount < 2) {
      await sleep(2000);
      return extractCardInfo(base64Image, mimeType, plan, keyConfig, retryCount + 1);
    }
    throw error;
  }
};

export const detectBusinessCards = async (base64Image: string, mimeType: string = 'image/jpeg', keyConfig?: ApiKeyConfig): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  try {
    const ai = getAiInstance(keyConfig);
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Image } },
          { text: "Detect business cards. Return boxes as JSON [[ymin, xmin, ymax, xmax]]." },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            boxes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  ymin: { type: Type.NUMBER }, xmin: { type: Type.NUMBER }, ymax: { type: Type.NUMBER }, xmax: { type: Type.NUMBER }
                },
                required: ["ymin", "xmin", "ymax", "xmax"]
              }
            }
          }
        }
      }
    });
    const data = JSON.parse(response.text || "{}");
    return data.boxes || [];
  } catch (e) {
    return [];
  }
};

