  }, [viewMode]);

  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定刪除？")) return;
    try {
      await deleteCardFromDB(id);
      setCards(prev => prev.filter(c => c.id !== id));
      if (selectedCardId === id) { setSelectedCardId(null); setSelectedCardData(null); setViewMode('file'); }
    } catch (e) {}
  };

  const performTask = useCallback(async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const currentConfig = task.apiKeyConfig || apiKeyConfig;
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg', plan, currentConfig);

      const st = tasksRef.current.find(t => t.id === task.id);
      if (st && st.status === 'cancelled') return;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(), ...info, scannedAt: Date.now(),
        source: 'QS Hub Scanner', imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      const { imageUrl, ...meta } = newCard;
      setCards(prev => [meta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', resultCardId: newCard.id } : t));
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  }, [apiKeyConfig, plan, isProcessing]);

  useEffect(() => {
    if (!isProcessing) {
      const next = tasks.find(t => t.status === 'pending');
      if (next) performTask({...next, plan}); 
    }
  }, [tasks, isProcessing, performTask]); 

  const handleShareMobile = async (card: BusinessCardData) => {
    if (!navigator.share) { alert("此瀏覽器不支援分享功能"); return; }
    const text = `名片資訊：\n姓名：${card.firstName} ${card.lastName}\n公司：${card.company}\n職稱：${card.title}\nEmail：${card.email}\n電話：${card.phone}`;
    try {
      await navigator.share({ title: 'QS Hub 名片分享', text: text });
    } catch (e) { console.log('Share failed', e); }
  };

  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;
    setIsExporting(true);
    try {
      const XLSX = await import('xlsx');
      const data = targetCards.map(c => ({ '來源': c.source, '姓名': `${c.firstName} ${c.lastName}`, '公司': c.company, '職稱': c.title, 'Email': c.email }));
      const ws = XLSX.utils.json_to_sheet(data);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Cards");
      XLSX.writeFile(wb, `QS_Export_${Date.now()}.xlsx`);
    } catch (e) { alert("匯出失敗"); } finally { setIsExporting(false); }
  };

  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64.split(',')[1], 'image/jpeg', apiKeyConfig);
      setCropRegions(boxes.map(box => ({
        id: crypto.randomUUID(), x: (box.xmin / 1000) * 100, y: (box.ymin / 1000) * 100, w: ((box.xmax - box.xmin) / 1000) * 100, h: ((box.ymax - box.ymin) / 1000) * 100
      })));
    } catch (e) {} finally { setIsAiDetecting(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const first = files[0];
    if (first.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const pdf = await pdfjs.getDocument(new Uint8Array(ev.target?.result as ArrayBuffer)).promise;
            const page = await pdf.getPage(1);
            const viewport = page.getViewport({ scale: 2 });
            const canvas = document.createElement('canvas');
            const context = canvas.getContext('2d');
            canvas.height = viewport.height; canvas.width = viewport.width;
            if (context) {
                await page.render({ canvasContext: context, viewport }).promise;
                const b64 = canvas.toDataURL('image/jpeg');
                setCropperImage(b64); setCropRegions([]); setViewMode('cropper'); autoDetectInCropper(b64);
            }
        };
        reader.readAsArrayBuffer(first);
        return;
    }
    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (ev) => {
            const b64 = ev.target?.result as string;
            setCropperImage(b64); setCropRegions([]); setViewMode('cropper'); autoDetectInCropper(b64);
        };
        reader.readAsDataURL(first);
        return;
    }
    const currentSnapshot = { ...apiKeyConfig };
    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID(); filesMap.current.set(id, f);
      const previewUrl = await new Promise<string>(res => {
        const r = new FileReader(); r.onload = ev => res(ev.target?.result as string); r.readAsDataURL(f);
      });
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl, apiKeyConfig: currentSnapshot });
    }
    setTasks(prev => [...prev, ...newTasks]); setViewMode('tasks');
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const cx = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const cy = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return { x: ((cx - rect.left) / rect.width) * 100, y: ((cy - rect.top) / rect.height) * 100 };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' = 'draw', cropId?: string) => {
    const pos = getMousePos(e); setStartPos(pos);
    if (action === 'draw') { setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 }); setIsDrawing(true); setActiveCropId(null); }
    else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) { setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) }); }
    else if (isMoving && activeCropId && initialRect) { setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r)); }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) setCropRegions(prev => [...prev, { ...currentRect, id: crypto.randomUUID() }]);
    setIsDrawing(false); setIsMoving(false); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image(); sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    const currentSnapshot = { ...apiKeyConfig };
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i]; const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH; const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl: URL.createObjectURL(blob), apiKeyConfig: currentSnapshot });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); setCropperImage(null); setViewMode('tasks');
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      <aside className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r lg:w-[320px] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-5 lg:p-6 bg-white shrink-0 sticky top-0" style={{ paddingTop: 'calc(1.25rem + var(--sat))' }}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3.5"><div className="w-10 h-10 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white"><i className="fa-solid fa-bahai"></i></div><div><h2 className="text-[15px] font-bold">QS HUB</h2><p className="text-[10px] text-slate-400 font-medium">Scanner Pro</p></div></div>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="w-10 h-10 bg-slate-50 rounded-full"><i className="fa-solid fa-xmark"></i></button>}
          </div>
          <div className="mb-6 bg-slate-50 p-3 rounded-xl border border-slate-200">
             <div className="flex items-center gap-2 mb-3 px-1"><div className={`w-2 h-2 rounded-full animate-pulse ${apiKeyConfig.source === 'env' ? 'bg-indigo-500' : 'bg-emerald-500'}`}></div><span className="text-[10px] font-bold uppercase text-slate-700">{apiKeyConfig.source === 'env' ? 'System Key' : apiKeyConfig.source === 'custom' ? 'Custom Key' : 'AI Studio'}</span></div>
             <button onClick={() => setShowKeyModal(true)} className="w-full py-2.5 bg-white border border-indigo-200 text-indigo-600 rounded-lg text-[10px] font-bold shadow-sm">設定 API KEY (Settings)</button>
          </div>
          <div className="bg-slate-100 p-1 rounded-xl flex gap-1 mb-4">
            <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
            <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
            <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
          </div>
          <div className="flex gap-2">
            <button onClick={() => handleShareOrExport('all')} className="flex-1 py-3 bg-white border border-slate-200 text-slate-600 rounded-lg text-[11px] font-bold"><i className="fa-solid fa-database mr-2"></i>全資料</button>
            <button onClick={() => handleShareOrExport(activeCategory)} className="flex-1 py-3 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[11px] font-bold"><i className="fa-solid fa-file-excel mr-2"></i>匯出</button>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-2 bg-slate-50/50 pb-20 lg:pb-3">
           <div className="grid grid-cols-2 gap-2 pb-10 px-1">
             {cards.filter(c => c.category === activeCategory).length === 0 ? (
                <div className="col-span-2 flex flex-col items-center justify-center py-10 text-slate-400"><i className="fa-regular fa-folder-open text-3xl mb-2 opacity-50"></i><span className="text-xs">目前無資料</span></div>
             ) : (
                cards.filter(c => c.category === activeCategory).map(c => (
                  <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); if(isMobile) setIsSidebarOpen(false); }} className={`group relative p-3 rounded-xl cursor-pointer transition-all border flex flex-col items-center text-center gap-2 ${selectedCardId === c.id ? 'bg-white border-indigo-500 shadow-lg' : 'bg-white border-slate-200 hover:border-slate-300'}`}>
                    <button onClick={(e) => handleDeleteCard(e, c.id)} className="absolute top-2 right-2 w-7 h-7 bg-white/80 hover:bg-red-500 text-slate-400 hover:text-white rounded-full flex items-center justify-center z-20"><i className="fa-solid fa-trash-can text-[10px]"></i></button>
                    <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${selectedCardId === c.id ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>{c.lastName?.charAt(0) || '?'}{c.firstName?.charAt(0) || '?'}</div>
                    <div className="w-full min-w-0"><div className="font-bold text-[11px] mb-0.5 truncate">{c.firstName} {c.lastName}</div><div className="text-[9px] text-slate-400 truncate uppercase">{c.company}</div></div>
                  </div>
               ))
             )}
           </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden">
        <header className={`h-16 px-4 border-b border-slate-200 flex items-center justify-between bg-white/80 backdrop-blur-xl shrink-0 z-[60] ${viewMode === 'detail' && isMobile ? 'hidden' : 'flex'}`} style={{ paddingTop: 'var(--sat)' }}>
           <div className="flex items-center gap-3 w-full">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 bg-white border border-slate-200 rounded-xl"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100 p-1 rounded-2xl overflow-x-auto gap-1">
                {isMobile && <NavBtn icon="fa-camera" label="掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />}
                <NavBtn icon={isMobile ? "fa-upload" : "fa-print"} label={isMobile ? "上傳" : "掃描匯入"} active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCardId && <><div className="w-px h-4 bg-slate-300 mx-1"></div><NavBtn icon="fa-id-card" label="核對" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} /></>}
             </nav>
           </div>
        </header>

        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'camera' && <CameraScanner onCapture={async (b64) => { 
                  const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                  const blob = await res.blob(); filesMap.current.set(id, blob);
                  setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, plan, previewUrl: `data:image/jpeg;base64,${b64}`, apiKeyConfig: { ...apiKeyConfig } }]);
                  setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />}

          {viewMode === 'file' && (
            <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp">
              <div className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white text-center shadow-lg cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl text-white animate-float"><i className={`fa-solid ${isMobile ? 'fa-cloud-arrow-up' : 'fa-print'} text-3xl`}></i></div>
                <h3 className="text-2xl font-extrabold text-slate-800 mb-3">{isMobile ? '上傳名片照片' : '匯入掃描檔案'}</h3>
                <p className="text-slate-400 text-sm mb-10">支援 PDF, JPG, PNG 格式</p>
                <div className="inline-flex items-center px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold shadow-lg">選擇檔案</div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" multiple onChange={handleFileUpload} />
              </div>
            </div>
          )}

          {viewMode === 'cropper' && cropperImage && (
             <div className="h-full flex flex-col bg-slate-100 animate-fadeIn" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                <div className="flex items-center justify-between p-4 bg-white border-b shrink-0 z-[100]">
                    <div className="flex gap-4 items-center"><div><h2 className="text-[15px] font-bold">智慧裁切</h2><p className="text-[10px] text-slate-400">{cropRegions.length} 張名片</p></div></div>
                    <div className="flex gap-3"><button onClick={() => setViewMode('file')} className="px-4 py-2 text-xs font-bold text-slate-500">取消</button><button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg">開始批次分析</button></div>
                </div>
                <div className="flex-1 overflow-auto p-12 flex items-start justify-center relative select-none" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                    <div className="relative shadow-2xl bg-white transition-transform origin-top-left">
                        {(isRenderingPdf || isAiDetecting) && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-pulse"><span className="text-xs font-bold">處理中...</span></div>}
                        <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                        <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
                        {cropRegions.map(crop => (
                            <div key={crop.id} className={`absolute border-2 z-20 ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}></div>
                        ))}
                    </div>
                </div>
             </div>
          )}

          {viewMode === 'tasks' && (
            <div className="max-w-2xl mx-auto p-4 lg:p-12 h-full overflow-y-auto pb-32">
              <div className="flex items-center justify-between mb-6"><h2 className="text-xl lg:text-2xl font-bold">處理佇列</h2>{tasks.length > 0 && <button onClick={() => setTasks([])} className="text-xs font-bold text-red-500">清除清單</button>}</div>
              {tasks.length === 0 ? <div className="text-center py-20 text-slate-300">目前無任務</div> : (
                  <div className="space-y-3">
                    {tasks.map(t => (
                      <div key={t.id} className="p-4 bg-white border rounded-2xl flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-4 min-w-0">{t.previewUrl && <img src={t.previewUrl} className="w-12 h-12 rounded-lg object-cover border shrink-0" alt="p" /><div className="min-w-0"><div className="font-bold text-sm truncate">{t.fileName}</div><div className="text-[10px] font-bold text-slate-400 uppercase">{t.status}</div></div></div>
                        <div className="flex gap-2">
                            {t.status === 'completed' && <button onClick={() => { if(t.resultCardId) { setSelectedCardId(t.resultCardId); setViewMode('detail'); } }} className="w-8 h-8 flex items-center justify-center text-slate-300"><i className="fa-solid fa-chevron-right"></i></button>}
                        </div>
                      </div>
                    ))}
                  </div>
              )}
            </div>
          )}

          {selectedCardData && viewMode === 'detail' && (
            <div className="h-full flex flex-col lg:flex-row animate-fadeIn">
               <div className={`relative flex flex-col bg-black overflow-hidden ${isMobile ? 'h-[40vh]' : 'w-[45%] border-r border-slate-800'}`}>
                  <div className="absolute top-4 right-4 z-[70] flex gap-2">
                    <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-black/40 rounded-xl text-white"><i className="fa-solid fa-rotate-right"></i></button>
                    <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-xl text-white"><i className="fa-solid fa-expand"></i></button>
                  </div>
                  <div className="flex-1 w-full h-full relative overflow-hidden p-4 flex items-center justify-center">
                    {selectedCardData.imageUrl && <img src={selectedCardData.imageUrl} className="shadow-2xl transition-transform" style={{ transform: `rotate(${rotation}deg)`, maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} />}
                  </div>
               </div>
               <div className="flex-1 overflow-y-auto bg-white p-5 lg:p-12 space-y-6 pb-32 lg:pb-12">
                    <header className="border-b pb-6"><span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase rounded-md">{selectedCardData.category}</span><h1 className="text-2xl font-extrabold mt-3 truncate">{selectedCardData.firstName} {selectedCardData.lastName}</h1><p className="text-indigo-600 font-semibold">{selectedCardData.title}</p></header>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4"><Field label="Company" value={selectedCardData.company} translation={selectedCardData.translations?.company} /><Field label="Email" value={selectedCardData.email} icon="fa-envelope" /><Field label="Phone" value={selectedCardData.phone} icon="fa-phone" /></div>
                    <div className="p-4 bg-slate-50 rounded-xl border text-xs text-slate-600">{selectedCardData.reasoning}</div>

                    {/* 手機端底部工具列 */}
                    {isMobile && (
                      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-xl border-t border-slate-200 z-[90] flex gap-3 shadow-[0_-10px_20px_rgba(0,0,0,0.05)]" style={{ paddingBottom: 'calc(1.5rem + var(--sab))' }}>
                        <button onClick={() => setViewMode('file')} className="flex-1 bg-slate-100 text-slate-800 py-3.5 rounded-2xl font-bold text-sm">返回</button>
                        <button onClick={() => handleShareMobile(selectedCardData)} className="flex-1 bg-emerald-500 text-white py-3.5 rounded-2xl font-bold text-sm shadow-lg flex items-center justify-center gap-2"><i className="fa-solid fa-share-nodes"></i>分享資訊</button>
                        <button onClick={() => handleShareOrExport(selectedCardData.category)} className="flex-1 bg-indigo-600 text-white py-3.5 rounded-2xl font-bold text-sm shadow-lg">匯出 Excel</button>
                      </div>
                    )}
               </div>
            </div>
          )}
        </div>

        {/* API Key Modal with Password */}
        {showKeyModal && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 animate-scaleIn">
                    <h3 className="text-lg font-bold mb-1">API Key 設定</h3>
                    <p className="text-xs text-slate-500 mb-6">請選擇 API Key 來源。系統金鑰需密碼驗證。</p>
                    <div className="space-y-3 mb-6">
                        <div onClick={() => { setApiKeyConfig({ source: 'env' }); setPasswordError(false); }} className={`p-4 rounded-xl border-2 cursor-pointer flex items-center gap-4 ${apiKeyConfig.source === 'env' ? 'border-indigo-500 bg-indigo-50' : 'border-slate-100'}`}><div className={`w-5 h-5 rounded-full border-2 ${apiKeyConfig.source === 'env' ? 'border-indigo-500' : 'border-slate-300'} flex items-center justify-center`}>{apiKeyConfig.source === 'env' && <div className="w-2 h-2 rounded-full bg-indigo-500"></div>}</div><div className="font-bold text-sm">系統預設 (管理員金鑰)</div></div>
                        {hasAiStudio && <div onClick={() => { setApiKeyConfig({ source: 'aistudio' }); setPasswordError(false); }} className={`p-4 rounded-xl border-2 cursor-pointer flex items-center gap-4 ${apiKeyConfig.source === 'aistudio' ? 'border-indigo-500 bg-indigo-50' : 'border-slate-100'}`}><div className={`w-5 h-5 rounded-full border-2 ${apiKeyConfig.source === 'aistudio' ? 'border-indigo-500' : 'border-slate-300'} flex items-center justify-center`}>{apiKeyConfig.source === 'aistudio' && <div className="w-2 h-2 rounded-full bg-indigo-500"></div>}</div><div className="font-bold text-sm">Google AI Studio</div></div>}
                        <div onClick={() => { setApiKeyConfig({ ...apiKeyConfig, source: 'custom' }); setPasswordError(false); }} className={`p-4 rounded-xl border-2 cursor-pointer ${apiKeyConfig.source === 'custom' ? 'border-indigo-500 bg-indigo-50' : 'border-slate-100'}`}>
                             <div className="flex items-center gap-4 mb-2"><div className={`w-5 h-5 rounded-full border-2 ${apiKeyConfig.source === 'custom' ? 'border-indigo-500' : 'border-slate-300'} flex items-center justify-center`}>{apiKeyConfig.source === 'custom' && <div className="w-2 h-2 rounded-full bg-indigo-500"></div>}</div><div className="font-bold text-sm">自訂金鑰 (Custom)</div></div>
                             {apiKeyConfig.source === 'custom' && <input type="text" placeholder="貼上 API Key" className="w-full mt-2 p-2 border rounded-lg text-xs" value={tempCustomKey} onChange={(e) => setTempCustomKey(e.target.value)} onClick={(e) => e.stopPropagation()} />}
                        </div>
                    </div>

                    {(apiKeyConfig.source === 'env' || apiKeyConfig.source === 'aistudio') && (
                      <div className="mb-6 p-4 bg-slate-50 border border-slate-200 rounded-xl animate-fadeIn">
                          <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">請輸入管理密碼</label>
                          <input type="password" placeholder="密碼 (如: 1234)" className={`w-full p-2.5 border rounded-lg text-sm ${passwordError ? 'border-red-500 bg-red-50' : 'border-slate-200 focus:ring-2 focus:ring-indigo-500'}`} value={systemPassword} onChange={(e) => setSystemPassword(e.target.value)} />
                          {passwordError && <p className="mt-1 text-[10px] font-bold text-red-500">密碼錯誤，請重新輸入。</p>}
                      </div>
                    )}

                    <button onClick={handleSaveApiKeyConfig} disabled={apiKeyConfig.source === 'custom' && tempCustomKey.trim() === ''} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-lg disabled:opacity-50">確認套用</button>
                    {localStorage.getItem('qs_api_config') && <button onClick={() => setShowKeyModal(false)} className="w-full mt-2 py-2 text-slate-400 text-xs font-bold">取消變更</button>}
                </div>
            </div>
        )}

        {isImageZoomed && selectedCardData && <div className="fixed inset-0 z-[300] bg-black flex items-center justify-center p-4" onClick={() => setIsImageZoomed(false)}><img src={selectedCardData.imageUrl} className="max-w-none w-full lg:w-auto lg:h-[90vh] object-contain" style={{ transform: `rotate(${rotation}deg)` }} /></div>}
      </main>

      <style>{`
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        .animate-fadeInUp { animation: fadeInUp 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        .animate-scaleIn { animation: scaleIn 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) forwards; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes scaleIn { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-10px); } }
        .animate-float { animation: float 4s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

const Field = React.memo(({ label, value, translation, icon, className }: any) => {
  if (!value) return null;
  const [copied, setCopied] = useState(false);
  return (
    <div className={`min-w-0 ${className}`}>
      <div className="flex justify-between mb-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</label><button onClick={() => { navigator.clipboard.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="text-[9px] font-bold text-indigo-400 uppercase">{copied ? 'Copied' : 'Copy'}</button></div>
      <div className="bg-slate-50 border p-3.5 rounded-xl text-[13px] font-semibold text-slate-700">{value}{translation && translation !== value && <div className="mt-2 pt-2 border-t text-xs text-slate-500">{translation}</div>}</div>
    </div>
  );
});

const CompactTab = React.memo(({ label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex-1 py-2 px-1 rounded-lg transition-all flex flex-col items-center justify-center min-w-0 ${active ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>
    <span className="text-[9px] font-bold uppercase truncate w-full text-center">{label}</span>
    <span className={`text-[10px] font-extrabold ${active ? 'text-indigo-600' : 'text-slate-400'}`}>{count}</span>
  </button>
));

const NavBtn = React.memo(({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex items-center gap-2 py-2 px-3 rounded-xl transition-all font-bold text-[10px] uppercase whitespace-nowrap active:scale-95 ${active ? 'bg-slate-900 text-white' : 'text-slate-500'}`}>
    <i className={`fa-solid ${icon}`}></i><span className="hidden sm:inline">{label}</span>
  </button>
));

export default App;
